    /** Widen the X box after t() — converted clips all give zero-width
     *  X at the arm states; the real ax61 hitboxes live in unconverted
     *  clip71 (flagged gap). */
    private fun widenX(e: Entity, x0: Int, x2: Int, y0: Int, y2: Int) {
