        ridePlayer(w, e); p.x1 = 0                          // g.g() true
        w.npcFsm.tickPlatform(e, w, p)
        assertEquals(6, e.S, "x1<=0 blocks board")
        ridePlayer(w, e, 50); p.x1 = 90
        w.npcFsm.tickPlatform(e, w, p)
        assertEquals(6, e.S, "aS.S==50 blocks board")
    }

