        assertEquals(4, e.Z[1], "Z[1]-- per tick")
        ridePlayer(w, e, 34); p.ga = e
        w.npcFsm.tickPlatform(e, w, p)
        assertNull(p.ga, "S34 -> L34 release")
    }

